package grpc_test

import (
 "testing"
 oldproto "github.com/golang/protobuf/proto"
 "google.golang.org/grpc/codes"
 "google.golang.org/grpc/encoding"
 _ "google.golang.org/grpc/encoding/proto"
 "google.golang.org/grpc/internal/binarylog"
 legacy "google.golang.org/grpc/reflection/grpc_testing_not_regenerate"
 "google.golang.org/grpc/status"
)

func TestReviewLegacyCodec(t *testing.T) {
 msg := &legacy.SearchRequestV3{Query: "hello"}
 data, err := oldproto.Marshal(msg)
 if err != nil {t.Fatal(err)}
 c := encoding.GetCodec("proto")
 if _, err := c.Marshal(msg); err != nil {t.Errorf("Marshal: %v",err)}
 if err := c.Unmarshal(data, &legacy.SearchRequestV3{}); err != nil {t.Errorf("Unmarshal: %v",err)}
}
func TestReviewLegacyStatus(t *testing.T) {
 s, err := status.New(codes.Internal,"x").WithDetails(&legacy.SearchRequestV3{Query:"hello"})
 if err != nil {t.Fatal(err)}
 if _,ok := s.Details()[0].(*legacy.SearchRequestV3); !ok {t.Fatalf("Details returned %T, want *SearchRequestV3", s.Details()[0])}
}
func TestReviewLegacyBinarylog(t *testing.T) {
 msg := &legacy.SearchRequestV3{Query:"hello"}
 ml := binarylog.NewTruncatingMethodLogger(100,100)
 for _, c := range []binarylog.LogEntryConfig{&binarylog.ClientMessage{Message:msg},&binarylog.ServerMessage{Message:msg}} {
   e := ml.Build(c)
   if len(e.GetMessage().Data)==0 {t.Errorf("%T logged empty data for a nonempty message",c)}
 }
}
EOF
