package transport
import (
 "testing"
 "strings"
 "time"
 "google.golang.org/protobuf/types/known/durationpb"
 lrs "github.com/envoyproxy/go-control-plane/envoy/service/load_stats/v3"
 "google.golang.org/grpc/internal/grpclog"
)
type reviewStream struct { lrsStream; interval *durationpb.Duration }
func (s reviewStream) Recv() (*lrs.LoadStatsResponse,error) {return &lrs.LoadStatsResponse{LoadReportingInterval:s.interval},nil}
func TestReviewIntervalError(t *testing.T) {
 tr := &Transport{logger:grpclog.NewPrefixLogger(grpclog.Logger, "test")}
 _,_,err := tr.recvFirstLoadStatsResponse(reviewStream{interval:&durationpb.Duration{Nanos:1000000000}})
 if err == nil {t.Fatal("invalid interval accepted")}
 if strings.Contains(err.Error(),"<nil>") {t.Errorf("missing validation reason: %v", err)}
}
func TestReviewIntervalOverflow(t *testing.T) {
 tr := &Transport{logger:grpclog.NewPrefixLogger(grpclog.Logger, "test")}
 _,interval,err := tr.recvFirstLoadStatsResponse(reviewStream{interval:&durationpb.Duration{Seconds:-10000000000}})
 if err == nil {
   t.Errorf("overflow accepted: %v",interval)
   defer func(){if r:=recover(); r!=nil {t.Errorf("sendLoads ticker panics: %v",r)}}()
   time.NewTicker(interval).Stop()
 }
}
EOF
